local crypto=require("lib.crypto")local M={}local SLOT_COUNT=32 local DECOY_GROUPS=15 local ALNUM="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"M.SLOT_COUNT=SLOT_COUNT local function shuffle(list)local out={}for i,v in ipairs(list)do out[i]=v end for i=#out,2,-1 do local j=crypto.randomInt(i)+1 out[i],out[j]=out[j],out[i]end return out end local function slice(list,n)local out={}for i=1,n do out[i]=list[i]end return out end local function contains(list,v)for _,x in ipairs(list)do if x==v then return true end end return false end local function encodeField(value,key)local salt=crypto.randomBytes(#value)local ks=crypto.stream(key,salt,#value)return crypto.b64(crypto.xor(value,ks))..":"..crypto.b64(salt)end local function decodeField(field,key)local a,b=field:match("^([^:]*):(.*)$")local share,salt=crypto.unb64(a),crypto.unb64(b)return crypto.xor(share,crypto.stream(key,salt,#share))end function M.pack(value)if value:match("^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$")and value==value:lower()then local hex=value:gsub("-","")return(hex:gsub("%x%x",function(h)return string.char(tonumber(h,16))end))end if#value==16 then return value.."\0"end return value end local function unpack16(p)if#p==16 then local h=crypto.hex(p)return h:sub(1,8).."-"..h:sub(9,12).."-"..h:sub(13,16).."-"..h:sub(17,20).."-"..h:sub(21)end if#p==17 and p:byte(17)==0 then return p:sub(1,16)end return p end local function decoyFor(value)if#value==16 then return crypto.randomBytes(16)end local out={}for i=1,#value do local k=crypto.randomInt(#ALNUM)+1 out[i]=ALNUM:sub(k,k)end if#value==17 and value:byte(17)==0 then out[17]="\0"end return table.concat(out)end function M.layout()local all={}for i=0,SLOT_COUNT-1 do all[#all+1]=i end local join=slice(shuffle(all),5+crypto.randomInt(4))local free={}for _,i in ipairs(all)do if not contains(join,i)then free[#free+1]=i end end local solved=slice(shuffle(free),DECOY_GROUPS)local groups={}for k,target in ipairs(solved)do local pool={}for _,i in ipairs(all)do local later=false for m=k+1,#solved do if solved[m]==i then later=true end end if i~=target and not later then pool[#pool+1]=i end end local group=slice(shuffle(pool),3+crypto.randomInt(11))group[#group+1]=target groups[k]=group end return{join=join,groups=groups}end local function solve(target,group,slots)local acc=target for i=1,#group-1 do acc=crypto.xor(acc,slots[group[i]+1])end slots[group[#group]+1]=acc end function M.split(value,shape)local slots={}for i=1,SLOT_COUNT do slots[i]=crypto.randomBytes(#value)end solve(value,shape.join,slots)for _,group in ipairs(shape.groups)do solve(decoyFor(value),group,slots)end return slots end function M.encode(cfg)local k=crypto.randomBytes(32)local i=crypto.randomBytes(32)local shape=M.layout()local slots=M.split(M.pack(cfg.appValue or""),shape)local s={}for n,slot in ipairs(slots)do s[n]=encodeField(slot,k)end return{k=k,i=i,a=encodeField(cfg.appId or"",i),s=s,j=shape.join,u=cfg.serverUrl,v=cfg.appVersion,},shape.groups end function M.decode(data)local slots={}for n,field in ipairs(data.s)do slots[n]=decodeField(field,data.k)end local acc=slots[data.j[1]+1]for n=2,#data.j do acc=crypto.xor(acc,slots[data.j[n]+1])end return{appId=decodeField(data.a,data.i),appValue=unpack16(acc),serverUrl=data.u,appVersion=data.v,}end M.decodeField=decodeField return M
